    case 600:
        return int(QFont::DemiBold);
    case 700:
        return int(QFont::Bold);
    case 800:
        return int(QFont::ExtraBold);
    case 900:
        return int(QFont::Black);
    default:
        return int(QFont::Normal);
    }
}

