                 Command::insert_child(1, 2, u32::MAX),
                 Command::set_string_property(2, 0x1038, "play"), // ICON_NAME
                 Command::create_node(4, 0x30),                   // MEDIA_CONTROLLER (non-visual)
                 Command::insert_child(1, 4, u32::MAX),
