/// VStack layout: children stack top-to-bottom on the main (vertical) axis,
/// with the configured spacing between them, and default cross-axis stretch
/// aligns them on the left. Drives the real QML `ColumnLayout` and reads the
/// laid-out geometry (`render_once` forces a layout pass offscreen).
#[test]
fn vstack_lays_out_children_vertically() {
    with_qt(|| unsafe {
        let cmds = [
            Command::create_node(1, component_type::VSTACK),
            Command::create_node(2, component_type::TEXT),
            Command::create_node(3, component_type::TEXT),
            Command::insert_child(1, 2, u32::MAX),
            Command::insert_child(1, 3, u32::MAX),
            Command::insert_child(0, 1, u32::MAX),
            Command::set_property(1, property_id::SPACING, value_type::F32, 10.0f32.to_bits()),
            Command::set_property(2, property_id::HEIGHT, value_type::F32, 50.0f32.to_bits()),
            Command::set_property(3, property_id::HEIGHT, value_type::F32, 50.0f32.to_bits()),
            Command::set_text(2, "A"),
            Command::set_text(3, "B"),
        ];
        pathland_qt_layer_apply(cmds.as_ptr(), cmds.len() as u32);
        assert_eq!(pathland_qt_layer_render_once(), 1);

        let x2 = pathland_qt_layer_widget_position(2, 0);
        let y2 = pathland_qt_layer_widget_position(2, 1);
        let x3 = pathland_qt_layer_widget_position(3, 0);
        let y3 = pathland_qt_layer_widget_position(3, 1);
        let h2 = pathland_qt_layer_widget_size(2, 1);
        let mut bh = [0i8; 64];
        pathland_qt_layer_widget_prop_text(
            2,
            c"implicitHeight".as_ptr(),
            bh.as_mut_ptr(),
            bh.len() as u32,
        );
        let mut bw = [0i8; 64];
        pathland_qt_layer_widget_prop_text(
            2,
            c"implicitWidth".as_ptr(),
            bw.as_mut_ptr(),
            bw.len() as u32,
        );
        let mut sp = [0i8; 64];
        pathland_qt_layer_widget_prop_text(
            1,
            c"spacing".as_ptr(),
            sp.as_mut_ptr(),
            sp.len() as u32,
        );
        eprintln!(
            "VSTACK x2={x2} y2={y2} x3={x3} y3={y3} h2={h2} pref2={} fill2={} pref3={} fill3={} rootw={} rooth={} nkids={} spacing={}",
            pathland_qt_layer_widget_preferred(2, 1),
            pathland_qt_layer_widget_fill(2, 1),
            pathland_qt_layer_widget_preferred(3, 1),
            pathland_qt_layer_widget_fill(3, 1),
            pathland_qt_layer_widget_size(1, 0),
            pathland_qt_layer_widget_size(1, 1),
            pathland_qt_layer_widget_child_count(1),
            std::ffi::CStr::from_ptr(sp.as_ptr()).to_string_lossy(),
        );
        eprintln!(
            "  child2 implicitW={} implicitH={}",
            std::ffi::CStr::from_ptr(bw.as_ptr()).to_string_lossy(),
            std::ffi::CStr::from_ptr(bh.as_ptr()).to_string_lossy(),
        );
        for p in ["width", "height", "objectName", "y", "x"] {
            let mut b = [0i8; 64];
            let cprop = std::ffi::CString::new(p).unwrap();
            pathland_qt_layer_widget_prop_text(
                1,
                cprop.as_ptr(),
                b.as_mut_ptr(),
                b.len() as u32,
            );
            eprintln!("  layout {p}={}", std::ffi::CStr::from_ptr(b.as_ptr()).to_string_lossy());
        }

        assert!(
            (h2 - 50.0).abs() < 0.5,
            "child height is the fixed main-axis size (got {h2})"
        );
        assert!(
            y3 > y2,
            "second child stacks below the first (got y2={y2}, y3={y3})"
        );
        assert!(
            (x3 - x2).abs() < 0.5,
            "default stretch aligns children on the left (x2={x2}, x3={x3})"
        );
        assert!(
            (y3 - (y2 + h2) - 10.0).abs() < 0.5,
            "vertical spacing gap is applied (got {})",
            y3 - (y2 + h2)
        );
    });
}

