// Test hook: the node id of the topmost direct child of a parent, by draw order
// (Qt stacking: higher z wins; ties break by later child index — the spec's
// ZStack rule). Returns 0 when the parent has no widget children.
uint32_t pathland_qt_layer_top_child(uint32_t parent) {
    QQuickItem *p = findWidget(parent);
    if (!p) {
        return 0;
    }
    // Reverse map item -> node id (injected renderer layers aren't in g.widgets).
    std::unordered_map<QQuickItem *, uint32_t> idOf;
    idOf.reserve(g.widgets.size());
    for (auto &kv : g.widgets) {
        idOf[kv.second] = kv.first;
    }
    uint32_t top = 0;
    double topZ = 0;
    bool have = false;
    auto kids = p->childItems();
    for (QQuickItem *kid : kids) {
        auto it = idOf.find(kid);
        if (it == idOf.end()) {
            continue; // renderer-injected layer (bg/shadow/mouse area)
        }
        const double z = kid->z();
        // Later child wins ties (>=) per "equal → child index".
        if (!have || z >= topZ) {
            top = it->second;
            topZ = z;
            have = true;
        }
    }
    return top;
}
